mapper.select:
SELECT COALESCE(SUM(total_tokens), 0)
FROM dispatch_ai_usage
WHERE tenant_id = #{tenantId}
  AND usage_at >= #{since}
  AND agent_id = #{agentId}

SELECT COALESCE(SUM(credits), 0)
FROM (
    SELECT credits
    FROM dispatch_ai_usage
    WHERE tenant_id = #{tenantId}
      AND usage_at >= #{since}
      AND agent_id = #{agentId}
    UNION ALL
    SELECT credits
    FROM agent_conversation_usage
    WHERE tenant_id = #{tenantId}
      AND usage_at >= #{since}
      AND agent_id = #{agentId}
) merged

SELECT COUNT(DISTINCT workitem_id)
FROM dispatch_ai_usage
WHERE tenant_id = #{tenantId}
  AND usage_at >= #{since}
  AND agent_id = #{agentId}

SELECT COUNT(DISTINCT workitem_id)
FROM (
    SELECT workitem_id
    FROM dispatch_ai_usage
    WHERE tenant_id = #{tenantId}
      AND usage_at >= #{since}
      AND agent_id = #{agentId}
    UNION ALL
    SELECT workitem_id
    FROM agent_conversation_usage
    WHERE tenant_id = #{tenantId}
      AND usage_at >= #{since}
      AND workitem_id IS NOT NULL
      AND agent_id = #{agentId}
) merged

SELECT COUNT(*) FROM dispatch
WHERE tenant_id = #{tenantId} AND status = 'SUCCEEDED' AND attempt = 0 AND gmt_create >= #{since} AND is_deleted = 0
  AND agent_id = #{agentId}

SELECT COUNT(*) FROM dispatch
WHERE tenant_id = #{tenantId} AND gmt_create >= #{since} AND is_deleted = 0
  AND agent_id = #{agentId}

SELECT COUNT(*) FROM dispatch
WHERE tenant_id = #{tenantId} AND attempt > 0 AND gmt_create >= #{since} AND is_deleted = 0
  AND agent_id = #{agentId}

SELECT COUNT(*) FROM dispatch
WHERE tenant_id = #{tenantId} AND status IN ('FAILED', 'TIMEOUT') AND gmt_create >= #{since} AND is_deleted = 0
  AND agent_id = #{agentId}

SELECT COUNT(*) FROM audit_log
WHERE tenant_id = #{tenantId} AND gmt_create >= #{since}
  AND action IN ('DELETE', 'FORCE_PUBLISH', 'ROLE_CHANGE', 'PERMISSION_GRANT')

SELECT COUNT(*) FROM audit_log
WHERE tenant_id = #{tenantId} AND gmt_create >= #{since}
  AND action IN ('BLOCK', 'REJECT', 'DENY')

SELECT DATE(usage_at) as day, COALESCE(SUM(credits), 0) as credits
FROM (
    SELECT usage_at, credits
    FROM dispatch_ai_usage
    WHERE tenant_id = #{tenantId} AND usage_at >= #{since}
      AND agent_id = #{agentId}
    UNION ALL
    SELECT usage_at, credits
    FROM agent_conversation_usage
    WHERE tenant_id = #{tenantId} AND usage_at >= #{since}
      AND agent_id = #{agentId}
) merged
GROUP BY DATE(usage_at)
ORDER BY day DESC
LIMIT 7

SELECT merged.agent_id AS agentId,
       a.name AS agentName,
       COALESCE(SUM(merged.credits), 0) AS credits,
       COALESCE(SUM(merged.conversation_credits), 0) AS conversationCredits
FROM (
    SELECT agent_id, credits, 0 AS conversation_credits
    FROM dispatch_ai_usage
    WHERE tenant_id = #{tenantId}
      AND usage_at >= #{since}
      AND agent_id IS NOT NULL
      AND agent_id = #{agentId}
    UNION ALL
    SELECT agent_id, credits, credits AS conversation_credits
    FROM agent_conversation_usage
    WHERE tenant_id = #{tenantId}
      AND usage_at >= #{since}
      AND agent_id IS NOT NULL
      AND agent_id = #{agentId}
) merged
LEFT JOIN agent a
  ON a.id = merged.agent_id AND a.tenant_id = #{tenantId} AND a.is_deleted = 0
GROUP BY merged.agent_id, a.name
ORDER BY merged.agent_id

SELECT source, COALESCE(SUM(credits), 0) AS credits
FROM (
    SELECT 'DISPATCH' AS source, credits
    FROM dispatch_ai_usage
    WHERE tenant_id = #{tenantId}
      AND usage_at >= #{since}
      AND agent_id = #{agentId}
    UNION ALL
    SELECT CASE
               WHEN channel = 'WORKITEM_CLARIFICATION' THEN 'WORKITEM_CLARIFICATION'
               WHEN channel = 'PLATFORM_ASSISTANT' THEN 'PLATFORM_ASSISTANT'
               WHEN channel IN ('DINGTALK', 'FEISHU') THEN 'IM'
               ELSE 'OTHER_CONVERSATION'
           END AS source,
           credits
    FROM agent_conversation_usage
    WHERE tenant_id = #{tenantId}
      AND usage_at >= #{since}
      AND agent_id = #{agentId}
) merged
GROUP BY source

SELECT DATE_FORMAT(al.gmt_create, '%Y-%m-%d %H:%i:%s') as timestamp, CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(al.detail_json, '$.actorType')) = 'HUMAN' OR (JSON_UNQUOTE(JSON_EXTRACT(al.detail_json, '$.actorType')) IS NULL AND a.id IS NULL) THEN COALESCE(u.nickname, u.username, CONCAT('user-', al.actor_id)) ELSE COALESCE(a.name, CONCAT('agent-', al.actor_id)) END as worker, CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(al.detail_json, '$.actorType')) = 'HUMAN' OR (JSON_UNQUOTE(JSON_EXTRACT(al.detail_json, '$.actorType')) IS NULL AND a.id IS NULL) THEN 'HUMAN' ELSE 'AGENT' END as operatorType, al.action as eventType, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(al.detail_json, '$.summary')), CONCAT(al.target_type, '#', al.target_id)) as detail, as riskLevel FROM audit_log al LEFT JOIN agent a ON al.actor_id = a.id AND al.tenant_id = a.tenant_id LEFT JOIN `user` u ON al.actor_id = u.id AND u.is_deleted = 0 WHERE al.tenant_id = #{tenantId} AND al.gmt_create >= DATE_SUB(NOW(), INTERVAL
7 90 30
DAY)
AND = #{riskLevel}
AND a.id = #{workerId}
AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(al.detail_json) THEN al.detail_json ELSE '{}' END, '$.actorType')), 'HUMAN') = 'AGENT'
ORDER BY al.gmt_create DESC LIMIT #{limit} OFFSET #{offset}

